insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_theatre1_v1'
from (values
('117.315.c.1.A',2,'During an ensemble scene, an actor fixes her attention on her partner''s words and responds truthfully. Which theatre skill is she using?','["Listening and concentration", "Set painting", "Ticket sales", "Costume sewing"]'::jsonb,0,'Listening and focus drive believable scenes.','original'),
('117.315.c.1.A',2,'Why is cooperation important in a theatre class?','["Cooperation slows rehearsals", "Productions depend on everyone working together", "Each person works alone", "Only the director matters"]'::jsonb,1,'Theatre is collaborative.','original'),
('117.315.c.1.B',2,'Why do actors warm up before rehearsal?','["To avoid rehearsing", "To memorize lines", "To prepare the body and voice and prevent injury", "To skip costumes"]'::jsonb,2,'Warm-ups ready the instrument.','original'),
('117.315.c.1.B',2,'Which activity is a typical vocal warm-up?','["Painting flats", "Lifting scenery", "Selling tickets", "Humming and lip trills"]'::jsonb,3,'Humming and trills prepare the voice.','original'),
('117.315.c.1.C',2,'An actor performs an invisible rope-pulling action without speaking or props. This stage movement technique is ___.','["Mime", "Monologue", "Blocking only", "Soliloquy"]'::jsonb,0,'Mime uses gesture to show objects and actions.','original'),
('117.315.c.1.C',2,'Laban movement analysis helps actors understand what?','["Costume fabrics", "Qualities of effort such as weight, time and space", "Set blueprints", "Lighting cues"]'::jsonb,1,'Laban describes how movement is shaped.','original'),
('117.315.c.1.D',2,'Speaking with crisp consonants so that each word is understood is practicing good ___.','["Cueing", "Stage left", "Diction", "Blocking"]'::jsonb,2,'Diction is clarity of speech.','original'),
('117.315.c.1.D',2,'Which technique helps an actor project without strain?','["Holding the breath", "Yelling from the throat", "Whispering all lines", "Breathing from the diaphragm"]'::jsonb,3,'Support allows safe projection.','original'),
('117.315.c.1.E',3,'A student writes that her character is tall, impatient, clever and fearful of failure. She is describing the character''s what?','["Physical, intellectual and emotional attributes", "Set pieces", "Ticket price", "Light cues"]'::jsonb,0,'Character analysis covers traits.','original'),
('117.315.c.1.E',3,'Which is a social attribute of a character?','["Having brown eyes", "Being the new student in a school", "Speaking loudly", "Walking quickly"]'::jsonb,1,'Social attributes relate to relationships and status.','original'),
('117.315.c.1.F',2,'The part of the stage closest to the audience is called ___.','["Backstage", "Offstage", "Downstage", "Upstage"]'::jsonb,2,'Downstage is nearest the audience.','original'),
('117.315.c.1.F',2,'A written plan of actors'' movements on stage is known as ___.','["Casting", "Strike", "Tech", "Blocking"]'::jsonb,3,'Blocking sets movement.','original'),
('117.315.c.1.G',3,'If the lighting designer changes the color to blue, the mood of a scene may change. This shows what about theatre elements?','["They depend on each other", "They are unrelated", "Only acting matters", "Light is unimportant"]'::jsonb,0,'Elements are interdependent.','original'),
('117.315.c.1.G',3,'Why must costumes, set and sound agree with the director''s concept?','["To shorten rehearsal", "So the production tells one unified story", "To confuse audiences", "To increase budget"]'::jsonb,1,'Unity requires cooperation of all elements.','original'),
('117.315.c.1.H',3,'Which job oversees the artistic vision of a production?','["Box office manager", "Usher", "Director", "Ticket scanner"]'::jsonb,2,'Directors guide the vision.','original'),
('117.315.c.1.H',3,'The stage manager''s role is to do what?','["Design costumes", "Write the play", "Sell concessions", "Coordinate rehearsals and call cues during performances"]'::jsonb,3,'Stage managers run the show.','original'),
('117.315.c.1.I',2,'A good way to memorize lines is to do what?','["Repeat them aloud with the action in short sections", "Ignore them", "Read once", "Skip the hard parts"]'::jsonb,0,'Chunking and repetition help.','original'),
('117.315.c.1.I',2,'Why is it helpful to learn cues along with your lines?','["It removes the need to rehearse", "It tells you when your line comes in", "It makes lines longer", "It changes the script"]'::jsonb,1,'Cue lines trigger responses.','original'),
('117.315.c.1.J',2,'A basic rule of improvisation is to accept your partner''s idea and add to it. This is often called ___.','["Stop and think", "No, but", "Yes, and", "Wait and see"]'::jsonb,2,'Accepting and building is a core principle.','original'),
('117.315.c.1.J',2,'Which skill is most essential in an improvised scene?','["Checking costumes", "Reading the script", "Counting seats", "Listening to your scene partner"]'::jsonb,3,'Improv depends on responding.','original'),
('117.315.c.1.K',2,'Before climbing a ladder on set, a student should do what?','["Check that it is stable and have a spotter", "Climb quickly", "Skip checking", "Use a broken ladder"]'::jsonb,0,'Safety checks prevent falls.','original'),
('117.315.c.1.K',2,'Why should walkways backstage be kept clear?','["To fit more props", "To prevent trips and falls in the dark", "To look neat for photos", "To sell more tickets"]'::jsonb,1,'Clear paths prevent accidents.','original'),
('117.315.c.2.A',2,'Using the voice safely means doing what?','["Ignoring pain", "Shouting all day", "Using breath support and resting when hoarse", "Whispering strain"]'::jsonb,2,'Voice care prevents injury.','original'),
('117.315.c.2.A',2,'An actor with a sore ankle should do what before a stage fight rehearsal?','["Jump from platforms", "Run harder", "Hide it", "Tell the director and avoid risky movement"]'::jsonb,3,'Honest communication keeps actors safe.','original'),
('117.315.c.2.B',3,'A student invents an original character with a unique walk and voice. She is showing what?','["Creativity in personal expression", "Silence", "Copying", "Avoiding choices"]'::jsonb,0,'Creativity shapes personal choices.','original'),
('117.315.c.2.B',3,'Which statement best defines creativity in theatre?','["Avoiding risk", "Making original choices to express ideas", "Ignoring the script", "Repeating others exactly"]'::jsonb,1,'Creativity means original expression.','original'),
('117.315.c.2.C',3,'An actor changes volume and pace to show fear during a monologue. She is using what?','["Lighting", "Ticket stubs", "Voice to express thoughts and feelings", "Set design"]'::jsonb,2,'Voice conveys emotion.','original'),
('117.315.c.2.C',3,'Which vocal choice helps show an angry character?','["No sound", "A slow whisper only", "A sleepy drawl", "A sharper tone and faster pace"]'::jsonb,3,'Vocal qualities show emotion.','original'),
('117.315.c.2.D',3,'An actor uses what she knows about a character''s background and feelings to decide how to stand and speak. She is portraying a ___.','["Believable character", "Random role", "Set", "Prop"]'::jsonb,0,'Awareness builds believability.','original'),
('117.315.c.2.D',3,'Which source helps an actor create a believable character?','["Painting the set", "Observing real people and considering the character''s goals", "Memorizing a playbill", "Skipping the script"]'::jsonb,1,'Observation and motivation inform choices.','original'),
('117.315.c.2.E',3,'An actor shows boredom without words by slumping and sighing. She is expressing a feeling through ___.','["Stage tape", "Dialogue", "Non-verbal physical technique", "Lighting"]'::jsonb,2,'Body language conveys emotion.','original'),
('117.315.c.2.E',3,'Which is a non-verbal way to show surprise?','["A long speech", "A costume change", "A set strike", "A sudden step back with wide eyes"]'::jsonb,3,'Physical choices show emotion.','original'),
('117.315.c.2.F',3,'A group writes a short scene about a lost phone, rehearses it and revises the ending after feedback. What are they doing?','["Creating and refining an original scene", "Ordering tickets", "Painting a flat", "Reciting a published play"]'::jsonb,0,'Writing and revising are part of creation.','original'),
('117.315.c.2.F',3,'Which element makes a short monologue effective?','["A copied speech", "A clear character with a want and a change", "No conflict", "Random words"]'::jsonb,1,'Wants and change create interest.','original'),
('117.315.c.3.A',2,'Which is a technical theatre skill?','["Acting in a chorus", "Memorizing a monologue", "Operating a lighting board", "Singing harmony"]'::jsonb,2,'Light operation is technical.','original'),
('117.315.c.3.A',2,'Practicing technical theatre skills includes learning how to do what?','["Memorize lines only", "Play the lead", "Direct every scene", "Build and paint a simple set piece"]'::jsonb,3,'Tech work includes building and painting.','original'),
('117.315.c.3.B',3,'A student wears safety glasses while cutting wood for a flat. She is doing what?','["Applying technical skills safely", "Skipping the task", "Ignoring rules", "Taking risks"]'::jsonb,0,'Safety gear is part of tech skill.','original'),
('117.315.c.3.B',3,'Before operating a power saw in the shop, a student must do what?','["Use it without supervision", "Get training and permission", "Ask a friend to try", "Guess how it works"]'::jsonb,1,'Equipment requires training.','original'),
('117.315.c.3.C',3,'A student is asked to design the sound for a short show, deciding music and effects. Which role is she performing?','["Critic", "Understudy", "Designer", "Usher"]'::jsonb,2,'Designers create elements of the show.','original'),
('117.315.c.3.C',3,'The person who edits a filmed scene is performing what role?','["Usher", "Dresser", "Playwright", "Editor"]'::jsonb,3,'Editors shape recorded work.','original'),
('117.315.c.3.D',3,'A student shows up on time, learns lines and solves a problem when a prop breaks. She is demonstrating what?','["Responsibility, discipline and creative problem solving", "Avoidance", "Carelessness", "Gossip"]'::jsonb,0,'Professional habits support production.','original'),
('117.315.c.3.D',3,'What is a creative solution if a prop cup is missing during a scene?','["Leave the stage", "Use a similar item or adjust the action to continue", "Stop the show", "Blame others"]'::jsonb,1,'Quick solutions keep scenes moving.','original'),
('117.315.c.4.A',3,'A play set in the Great Depression shows what about theatre?','["It has no setting", "It repeats news only", "It can reflect life in a particular time and place", "It ignores history"]'::jsonb,2,'Plays reflect their setting.','original'),
('117.315.c.4.A',3,'Portraying a culture respectfully on stage requires what?','["Ignoring facts", "Stereotypes", "Guesswork", "Research and sensitivity"]'::jsonb,3,'Accurate portrayal requires research.','original'),
('117.315.c.4.B',3,'Greek theatre used masks and a chorus partly because of the huge outdoor spaces. This relates to which influence?','["Cultural and historical conditions", "Television", "Cell phones", "Modern lighting"]'::jsonb,0,'Context shapes theatrical conventions.','original'),
('117.315.c.4.B',3,'The Elizabethan stage influenced Shakespeare''s plays. This is an example of what?','["A game rule", "Historical influence on theatre", "A film effect", "A modern invention"]'::jsonb,1,'Playhouses shaped writing.','original'),
('117.315.c.4.C',3,'How did the invention of film change theatre?','["It ended stage plays", "It removed actors", "It offered new competition and storytelling ideas", "It banned costumes"]'::jsonb,2,'Media influenced theatre.','original'),
('117.315.c.4.C',3,'Streaming a live play online allows what?','["No audience", "Fewer actors", "Only local viewing", "Audiences far away to watch performances"]'::jsonb,3,'Electronic media extends reach.','original'),
('117.315.c.4.D',3,'Which ancient culture is credited with developing early drama in Athens?','["Greek", "Aztec", "Roman only", "Inuit"]'::jsonb,0,'Greek drama began in Athens.','original'),
('117.315.c.4.D',3,'Which playwright wrote Hamlet?','["Molière", "William Shakespeare", "Sophocles", "Anton Chekhov"]'::jsonb,1,'Shakespeare wrote Hamlet.','original'),
('117.315.c.4.E',3,'A play by Lorraine Hansberry, A Raisin in the Sun, is part of which tradition?','["Ancient Greek drama", "Commedia dell''arte", "United States multicultural drama", "Japanese noh"]'::jsonb,2,'Hansberry was an African American playwright.','original'),
('117.315.c.4.E',3,'Which American playwright is known for Death of a Salesman?','["Sam Shepard", "Neil Simon", "August Wilson", "Arthur Miller"]'::jsonb,3,'Miller wrote Death of a Salesman.','original'),
('117.315.c.4.F',3,'The American musical grew from various traditions. This is an example of a United States contribution to what?','["The performing arts", "Cooking only", "Architecture only", "Sports only"]'::jsonb,0,'Musical theatre is an American innovation.','original'),
('117.315.c.4.F',3,'Which is a U.S. contribution to the performing arts?','["Noh", "Broadway musical theatre", "Kabuki", "Greek chorus"]'::jsonb,1,'Broadway musicals are American.','original'),
('117.315.c.5.A',2,'During a live performance, audience members should do what?','["Film with flash", "Take calls", "Silence phones and watch quietly", "Talk loudly"]'::jsonb,2,'Etiquette respects performers.','original'),
('117.315.c.5.A',2,'At a formal theatre, applause is appropriate at what moment?','["During quiet dialogue", "While actors exit", "In the middle of a monologue", "At the end of the show or when the cast takes a bow"]'::jsonb,3,'Applause follows conventions.','original'),
('117.315.c.5.B',3,'A student reflects in a journal about what she learned and where she grew creatively. She is doing what?','["Evaluating herself as a creative being", "Copying others", "Ignoring work", "Avoiding reflection"]'::jsonb,0,'Reflection builds artistic identity.','original'),
('117.315.c.5.B',3,'Why is theatre considered an art form?','["It is only entertainment", "It expresses ideas through creative performance", "It requires no skill", "It is a game"]'::jsonb,1,'Art conveys meaning creatively.','original'),
('117.315.c.5.C',3,'A peer gives helpful feedback by naming a strength and a specific suggestion. This is ___.','["Silence", "Rude comments", "Constructive criticism", "Gossip"]'::jsonb,2,'Constructive means specific and kind.','original'),
('117.315.c.5.C',3,'When receiving criticism of your scene, you should do what?','["Argue", "Ignore everything", "Leave the room", "Listen openly and consider how to improve"]'::jsonb,3,'Open listening supports growth.','original'),
('117.315.c.5.D',3,'After seeing a school play, a student writes that the lighting shift in act two sharpened the tension. This is a ___.','["Specific observation in a review", "Prop list", "Gossip", "Vague opinion"]'::jsonb,0,'Precise detail supports evaluation.','original'),
('117.315.c.5.D',3,'Which is the most useful sentence in a theatre review?','["I liked it", "The actor''s pacing built suspense in the confrontation scene", "It was long", "It was good"]'::jsonb,1,'Specifics help readers.','original'),
('117.315.c.5.E',3,'A student writes about how a film''s camera angles shaped a character''s power. She is evaluating what?','["A ticket", "Her lunch", "Media with precise observations", "A rumor"]'::jsonb,2,'Evaluation uses specific detail.','original'),
('117.315.c.5.E',3,'Which detail strengthens an evaluation of a TV drama?','["The channel number", "The time slot only", "The commercial breaks", "How editing and sound created tension"]'::jsonb,3,'Technical details support analysis.','original'),
('117.315.c.5.F',2,'Which job is a career in theatre education?','["Drama teacher", "Pilot", "Surveyor", "Welder"]'::jsonb,0,'Teachers train students in theatre.','original'),
('117.315.c.5.F',2,'A person who manages a theatre''s budget and schedules works in what field?','["Mining", "Arts administration", "Forestry", "Plumbing"]'::jsonb,1,'Arts administrators handle operations.','original'),
('117.315.c.5.G',3,'A student builds an online portfolio with photos and a journal of her productions. She is using what?','["A script alone", "A paper airplane", "Technology to document her experiences", "A coupon"]'::jsonb,2,'Portfolios document growth.','original'),
('117.315.c.5.G',3,'Which is a good use of a theatre journal?','["Drawing only", "Storing coupons", "Hiding scripts", "Recording rehearsals, goals and reflections"]'::jsonb,3,'Journals track development.','original'),
('117.315.c.5.H',3,'Public speaking learned in theatre helps a student succeed in which career?','["Sales or law", "Only in acting", "Only in dance", "Never in sales"]'::jsonb,0,'Theatre skills transfer to many careers.','original'),
('117.315.c.5.H',3,'Teamwork learned in theatre helps students in college because it builds what?','["Distraction", "Collaboration skills", "Isolation", "Avoidance"]'::jsonb,1,'Collaboration is valued everywhere.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
